/* -------------------------------------------------------------------------------------------------
 * Loading bar: 2 px in the foreground color. Trickles while indeterminate, then completes.
 * -----------------------------------------------------------------------------------------------*/

// design-lint-ignore-next-line scale-zero: a progress bar at 0% is empty by definition, it never enters from it
const EMPTY_BAR = "scaleX(0)"

function LoadingBar({ loading, progress }: { loading: boolean; progress?: number }) {
  const ref = React.useRef<HTMLSpanElement>(null)
  const animation = React.useRef<Animation | null>(null)
  const [visible, setVisible] = React.useState(false)
  const shownAt = React.useRef(0)

  // Wait 150 ms before showing, so instant loads never flash a bar.
  React.useEffect(() => {
    if (!loading) return
    const id = window.setTimeout(() => {
      shownAt.current = performance.now()
      setVisible(true)
    }, 150)
    return () => window.clearTimeout(id)
  }, [loading])

  React.useEffect(() => {
    const el = ref.current
    if (!el || !visible) return
    const reduce = prefersReducedMotion()
    if (loading && progress === undefined) {
      animation.current?.cancel()
      el.style.opacity = "1"
      animation.current = reduce
        ? null
        : el.animate([{ transform: "scaleX(0.02)" }, { transform: "scaleX(0.9)" }], {
            duration: 8000,
            easing: "cubic-bezier(0.1, 0.7, 0.2, 1)",
            fill: "forwards",
          })
      if (reduce) el.style.transform = "scaleX(0.6)"
      return
    }
    if (loading && progress !== undefined) {
      animation.current?.cancel()
      animation.current = null
      el.style.opacity = "1"
      el.style.transform = `scaleX(${Math.max(0.02, Math.min(1, progress))})`
      return
    }
    // Done: finish the run, hold for the 400 ms minimum, then fade.
    const current = getComputedStyle(el).transform
    animation.current?.cancel()
    el.style.transform = current === "none" ? EMPTY_BAR : current
    const hold = Math.max(0, 400 - (performance.now() - shownAt.current))
    const finish = el.animate([{ transform: el.style.transform }, { transform: "scaleX(1)" }], {
      duration: reduce ? 0 : 180,
      easing: "cubic-bezier(0.23, 1, 0.32, 1)",
      fill: "forwards",
      delay: hold,
    })
    finish.onfinish = () => {
      el.style.transform = "scaleX(1)"
      const fade = el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 200, fill: "forwards" })
      fade.onfinish = () => {
        el.style.opacity = "0"
        el.style.transform = EMPTY_BAR
        setVisible(false)
      }
      animation.current = fade
    }
    animation.current = finish
  }, [loading, progress, visible])

  return (
    <span
      aria-hidden="true"
      data-slot="web-preview-loading-bar"
      className="pointer-events-none absolute inset-x-0 top-0 z-20 h-0.5 overflow-hidden"
    >
      <span
        ref={ref}
        className={cn(
