function LogIcon({ level }: { level: WebPreviewLogLevel }) {
  if (level === "error") return <CircleXIcon className="text-(color:--chatcn-red)" />
  if (level === "warn") return <TriangleAlertIcon className="text-(color:--chatcn-fg)" />
  if (level === "info") return <InfoIcon className="text-(color:--chatcn-fg-subtle)" />
