              "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-out) transition-transform duration-200 motion-reduce:transition-none",
              consoleOpen && "rotate-180",
            )}
          />
        </button>
        <span
          aria-live="polite"
          className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) ms-auto truncate pe-1.5"
        >
          {errorInfo ? "Failed to load" : loading && !empty ? "Loading…" : ""}
        </span>
      </div>
    </div>
  )
}

export default WebPreview

